# -*- coding: utf-8 -*-
"""UI-Strings DE/EN + Cron-Mappings für Ugreen NAS Admin (Public)."""

from __future__ import annotations

from functools import lru_cache

def _cron_de() -> dict:
    return {
        "Minute": {"Jede Minute": "*"} | {f"{i:02d}": str(i) for i in range(60)},
        "Stunde": {"Jede Stunde": "*"} | {f"{i:02d}": str(i) for i in range(24)},
        "Tag": {"Jeden Tag": "*"} | {f"{i:02d}": str(i) for i in range(1, 32)},
        "Monat": {
            "Jeden Monat": "*",
            "Januar (1)": "1",
            "Februar (2)": "2",
            "März (3)": "3",
            "April (4)": "4",
            "Mai (5)": "5",
            "Juni (6)": "6",
            "Juli (7)": "7",
            "August (8)": "8",
            "September (9)": "9",
            "Oktober (10)": "10",
            "November (11)": "11",
            "Dezember (12)": "12",
        },
        "Wochentag": {
            "Jeden Tag": "*",
            "Montag": "1",
            "Dienstag": "2",
            "Mittwoch": "3",
            "Donnerstag": "4",
            "Freitag": "5",
            "Samstag": "6",
            "Sonntag": "0",
        },
    }


def _cron_en() -> dict:
    months = [
        "January (1)",
        "February (2)",
        "March (3)",
        "April (4)",
        "May (5)",
        "June (6)",
        "July (7)",
        "August (8)",
        "September (9)",
        "October (10)",
        "November (11)",
        "December (12)",
    ]
    mon = {"Every month": "*"} | {months[i]: str(i + 1) for i in range(12)}
    return {
        "Minute": {"Every minute": "*"} | {f"{i:02d}": str(i) for i in range(60)},
        "Stunde": {"Every hour": "*"} | {f"{i:02d}": str(i) for i in range(24)},
        "Tag": {"Every day": "*"} | {f"{i:02d}": str(i) for i in range(1, 32)},
        "Monat": mon,
        "Wochentag": {
            "Every day": "*",
            "Monday": "1",
            "Tuesday": "2",
            "Wednesday": "3",
            "Thursday": "4",
            "Friday": "5",
            "Saturday": "6",
            "Sunday": "0",
        },
    }


def cron_mappings_for_lang(lang: str) -> dict:
    return _cron_de() if lang == "de" else _cron_en()


def _merge(*dicts) -> dict:
    o = {}
    for part in dicts:
        o.update(part)
    return o


