@lru_cache(maxsize=16384)
def _translate_plain(lang_code: str, key: str) -> str:
    d = TRANSLATIONS.get(lang_code) or TRANSLATIONS["de"]
    s = d.get(key)
    if s is None:
        if lang_code != "de":
            s = TRANSLATIONS["en"].get(key)
        if s is None:
            s = TRANSLATIONS["de"].get(key)
        if s is None:
            s = TRANSLATIONS["en"].get(key)
        if s is None:
            s = key
    return s


def translate(lang: str, key: str, **kwargs) -> str:
    code = str(lang or "").strip().lower()
    if TRANSLATIONS.get(code) is None:
        code = "de"
    # Handbuch-Button: nur DE als "Handbuch", alle anderen Sprachen "Manual".
    if key == "info.manual" and code != "de":
        code = "en"
    # Wunschverhalten: Dashboard-Texte nur in DE, sonst immer EN.
    if code != "de" and (key.startswith("dashboard.") or key.startswith("dash.")):
        code = "en"
    s = _translate_plain(code, key)
    if kwargs:
        try:
            return s.format(**kwargs)
        except (KeyError, ValueError):
            return s
    return s


SUPPORTED_LANGS = ("de", "en", "hr", "fr", "es", "it", "pl", "ru", "tr", "ko", "zh")
LANGUAGE_LABELS = {
    "de": "Deutsch",
    "en": "English",
    "hr": "Hrvatski",
    "fr": "Français",
    "es": "Español",
    "it": "Italiano",
    "pl": "Polski",
    "ru": "Русский",
    "tr": "Türkçe",
    "ko": "한국어",
    "zh": "中文",
}


def normalize_lang(lang: str, default: str = "de") -> str:
    code = str(lang or "").strip().lower()
    if code in SUPPORTED_LANGS:
        return code
    return default


def supported_languages() -> tuple[str, ...]:
    return SUPPORTED_LANGS


def language_label(code: str) -> str:
    c = normalize_lang(code, default="en")
    return LANGUAGE_LABELS.get(c, c)
